head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05312.xml";
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.trsIdx; // insert, update 구분
scwin.rowPos;
scwin.VListBzTpCd = LIST_BZ_TP_CD_201; //ETF 상장폐지
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // jackal_11.05.12 상장종목 여부 체크 추가

scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    //arrPar[1] = getObjectValue(txb_SearchNm);	// 명칭값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.fn_initItem();
        scwin.fn_isubook_read_sync();
        scwin.fn_list_sync();
    }
    //jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        buttonSet.setDisableStatus();
    }
};
scwin.fn_GetParRsn = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "05";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParRsn = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_Mst.NameString(1, "DELIST_RSN_CD") = (arrPar.length >= 1 ? arrPar[0] : "");*/
    X = (arrPar.length >= 1 ? arrPar[0] : "");
    txb_DELIST_RSN_DSC.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
    txb_GRND_REGUL_NM.setValue((arrPar.length >= 3 ? arrPar[2] : ""));
};



//신주인수권증권/증서수 조회
scwin.fn_isubook_read_sync = function() {
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchTotstkcnt&inputMessageId=DELISTING_INOUT&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};


//품목코드선택시 리스트 조회
scwin.fn_list_sync = function() {
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchlist&inputMessageId=DELISTING_INOUT&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


//그리드  더블 클릭시 조회
scwin.fn_read_sync = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchlistDbDetail&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_initItem = function() {
    buttonSet.setInsertStatus();
    dts_Isu.removeAll();
    dts_Isu.insertRow();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; //초기화 

};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_DELIST_DD) == "") {
        $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.ut.cGetToday("yyyymmdd") >= $c.stf.getObjectValue(edt_DELIST_DD)) {
        $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (scwin.fr_MktId == '2') {
        if ($c.stf.getObjectValue(txb_DELIST_RSN_DSC) == "") {
            $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        dts_Mst.setCellData(1, "DELIST_RSN_DSC", $c.stf.getObjectValue(txb_DELIST_RSN_DSC));
    } else if (scwin.fr_MktId == '1') {
        if (dts_Mst.getCellData(1, "DELIST_RSN_CD") == "") {
            $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }

    }
    if ($c.stf.getObjectValue(txb_GRND_REGUL_NM) == "") {
        $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_GRND_REGUL_NM, 200, "근거규정")) return false;
    return true;
};
scwin.fn_save = function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        //alert('[dts_Mst]'+dts_Mst.text);
        scwin.fn_trs();
    }
};
scwin.fn_update = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    if (scwin.trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Isu.setCellData(i, "ISU_CD", $c.stf.getObjectValue(txb_ISU_CD));
    }

    // 종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    dts_Mst.setCellData(1, "ISUR_CD", scwin.vIsurCd);

    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    trs_Save.Action = $c.lc.fn_encodeNSession("/Delisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveDelList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=2" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL;
    trs_Save.Post();
};
scwin.fn_dscl = async function() {
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
    	*/
    var OldGet = fn_GetPar;
    var OldSet = fn_SetPar;
    fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        if (scwin.fr_MktId == "1") {
            arr[0] = "68051C";
        } else if (scwin.fr_MktId == "2") {
            arr[0] = "70857";
        }
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = scwin.fr_MktId;
        arr[4] = "";
        if (scwin.fr_MktId == "1") {
            if (scwin.fr_SecuGrpId == SECUGRP_ID_EF || scwin.fr_SecuGrpId == SECUGRP_ID_FE) {
                arr[5] = ''; //코스콤 전송시 주권, ETF법인은 제목앞에 회사명을 붙이므로 주석처리.

            } else {
                arr[5] = $c.stf.getObjectValue(txb_ISU_NM);
            }
        } else if (scwin.fr_MktId == "2") {
            arr[5] = "";
        }

        //CopyDataSet( dts_Isu , param_dts_isu) ;
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        return arr.length;
    };
    fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    fn_GetPar = OldGet;
    fn_SetPar = OldSet;
};
scwin.fn_drft = function() {
    var OldGet = fn_GetPar;
    fn_GetPar = function(arr) {
        arr[0] = dts_List.getCellData(1, "BZ_PROCS_NO");
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    fn_GetPar = OldGet;
};


//function fn_makt() { }


scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    } else {
        scwin.fn_initItem();
        scwin.fn_isubook_read_sync();
        scwin.fn_list_sync();
    }
};
scwin.img_ISU_NM_onclick = function() {
    fn_GetPar = fn_GetParIsuCd;
    fn_SetPar = fn_SetParIsuCd;
    //fn_PopFindIsu(fr_SecuGrpId);		
    $c.lc.fn_PopFindIsuAll(scwin.fr_SecuGrpId); // jackal_11.05.12

};
scwin.img_DELIST_RSN_DSC_onclick = function() {
    fn_GetPar = fn_GetParRsn;
    fn_SetPar = fn_SetParRsn;
    $c.lc.fn_PopFindClssLstRsnCd(RSNCD_DELIST);
};
scwin.img_DELIST_DD_onclick = function() {
    popUpCalendar2(edt_DELIST_DD);
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_read_sync(row);
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    } else {
        if ($c.ut.cGetToday("yyyymmdd") <= $c.stf.getObjectValue(edt_DELIST_DD)) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus();
        }
    }
    // jackal_11.05.12
    if (scwin.vLIST_STAT_CD == "D") {
        buttonSet.setDisableStatus();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_initItem();
    scwin.fn_list_sync();
    if (buttonSet.status != "D") {
        // 삭제처리의 응답인 경우
        scwin.fn_read_sync(dts_List.getTotalRow());
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    buttonSet.setDrftInfo(btn_Drft, fn_drft); // 기안

    buttonSet.setInsertStatus();
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELISTING_ISU_INOUT";
    dts_Isu.reset();
    if (scwin.fr_MktId == '2') {
        $c.stf.showObj(panel_DELIST_RSN_DSC, false);
        txb_DELIST_RSN_DSC.setReadOnly(false);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#ffffff';
    }
};
